const $=id=>document.getElementById(id);
function clockFace(){const roman=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];return `<svg class="hanging-face" viewBox="0 0 240 240" aria-hidden="true"><circle cx="120" cy="120" r="112" fill="#252a25"/><circle cx="120" cy="120" r="104" fill="#eee5c8" stroke="#9c8c62" stroke-width="2"/><circle cx="120" cy="120" r="95" fill="none" stroke="#a69a78" stroke-width="1"/>${Array.from({length:60},(_,i)=>`<line x1="120" y1="${i%5===0?19:17}" x2="120" y2="${i%5===0?28:22}" stroke="#6b624e" stroke-width="${i%5===0?1.5:.6}" transform="rotate(${i*6} 120 120)"/>`).join('')}${roman.map((v,i)=>{const a=i*Math.PI/6;return `<text x="${120+81*Math.sin(a)}" y="${125-81*Math.cos(a)}" text-anchor="middle" fill="#4e493b" font-size="13" font-family="Georgia,serif">${v}</text>`;}).join('')}<g data-clock-hour><path d="M120 129V66" stroke="#353a30" stroke-width="6" stroke-linecap="round"/></g><g data-clock-minute><path d="M120 131V39" stroke="#353a30" stroke-width="4" stroke-linecap="round"/></g><g data-clock-second><path d="M120 140V29" stroke="#a16a46" stroke-width="1.4"/></g><circle cx="120" cy="120" r="5" fill="#766344"/></svg>`;}
export function installImmersive(cities,onChoose=()=>{}){let on=false,timer,lastPointer=0;const stored={};for(const [city,c]of Object.entries(cities)){const sign=document.createElement('div');sign.className='hanging-sign '+(c.id||city)+'-sign';sign.id=city+'-sign';sign.innerHTML=`<span class="rope rope-left"></span><span class="rope rope-right"></span><span class="sign-pin pin-left"></span><span class="sign-pin pin-right"></span>${clockFace()}<div class="hanging-digital" aria-hidden="true"></div><button type="button" class="hanging-city">${c.name}<small>${c.zone.replace('/',' / ')}</small></button><span class="sign-pin pin-bottom-left"></span><span class="sign-pin pin-bottom-right"></span>`;sign.setAttribute('role','group');sign.setAttribute('aria-label',`${c.name}懸掛時鐘，可拖曳位置`);sign.tabIndex=0;$(city+'-scene').append(sign);sign.querySelector('.hanging-city').addEventListener('click',()=>onChoose(city));let drag=null;sign.addEventListener('pointerdown',e=>{if(!on||e.button!==0||e.target.closest('button'))return;const r=sign.getBoundingClientRect(),parent=sign.parentElement.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:r.left-parent.left,top:r.top-parent.top};sign.setPointerCapture(e.pointerId);sign.classList.add('dragging');e.preventDefault();});sign.addEventListener('pointermove',e=>{if(!drag)return;const parent=sign.parentElement;const left=Math.max(8,Math.min(parent.clientWidth-sign.offsetWidth-8,drag.left+e.clientX-drag.x)),top=Math.max(20,Math.min(parent.clientHeight-sign.offsetHeight-20,drag.top+e.clientY-drag.y));sign.style.left=left+'px';sign.style.top=top+'px';sign.style.transform='none';});const end=()=>{drag=null;sign.classList.remove('dragging');};sign.addEventListener('pointerup',end);sign.addEventListener('pointercancel',end);sign.addEventListener('keydown',e=>{if(!on||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const r=sign.getBoundingClientRect(),p=sign.parentElement.getBoundingClientRect(),dx=e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0,dy=e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0;sign.style.left=Math.max(8,Math.min(p.width-r.width-8,r.left-p.left+dx))+'px';sign.style.top=Math.max(20,Math.min(p.height-r.height-20,r.top-p.top+dy))+'px';sign.style.transform='none';});}
const controls=document.createElement('div');controls.className='immersive-controls';controls.innerHTML='<span>移動時鐘可調整位置</span><button id="immersive-exit" aria-label="退出沉浸模式">↙ 返回一般模式 <kbd>Esc</kbd></button>';
document.body.append(controls);
const hint=document.createElement('div');hint.className='immersive-hint';hint.textContent='移動滑鼠或觸碰可顯示操作 · Esc 返回';document.body.append(hint);
const wake=()=>{if(!on)return;document.body.classList.remove('immersive-idle');clearTimeout(timer);timer=setTimeout(()=>document.body.classList.add('immersive-idle'),3000);};
async function enter(){on=true;document.body.classList.add('immersive');$('immerse').setAttribute('aria-pressed','true');for(const city of Object.keys(cities)){const s=$(city+'-sign');stored[city]={left:s.style.left,top:s.style.top,transform:s.style.transform};s.style.left=city==='left'?'74%':'26%';s.style.top='7%';s.style.transform='translateX(-50%)';}wake();try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();}catch{/* CSS edge-to-edge mode remains available when fullscreen is restricted. */}}
async function exit(){if(!on)return;on=false;clearTimeout(timer);document.body.classList.remove('immersive','immersive-idle');$('immerse').setAttribute('aria-pressed','false');if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}$('immerse').focus();}
$('immerse').addEventListener('click',()=>on?exit():enter());$('immersive-exit').addEventListener('click',exit);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&on&&!document.querySelector('dialog[open]'))exit();else wake();});document.addEventListener('fullscreenchange',()=>{if(on&&!document.fullscreenElement)exit();});document.addEventListener('pointermove',()=>{const now=performance.now();if(now-lastPointer>150){lastPointer=now;wake();}});document.addEventListener('pointerdown',wake);document.addEventListener('focusin',wake);window.addEventListener('resize',()=>{if(on)for(const city of Object.keys(cities)){const sign=$(city+'-sign');sign.style.left=city==='left'?'74%':'26%';sign.style.top='7%';sign.style.transform='translateX(-50%)';}});
return {update(city,p){const sign=$(city+'-sign'),c=cities[city];if(sign.dataset.location!==c.id){sign.dataset.location=c.id;sign.className='hanging-sign '+c.id+'-sign';const label=sign.querySelector('.hanging-city');label.innerHTML=c.name+'<small>'+c.zone.replace('/',' / ')+'</small>';label.setAttribute('aria-label','更換城市，目前'+c.name);}sign.querySelector('[data-clock-hour]').setAttribute('transform',`rotate(${(p.hour%12)*30+p.minute*.5} 120 120)`);sign.querySelector('[data-clock-minute]').setAttribute('transform',`rotate(${p.minute*6+p.second*.1} 120 120)`);sign.querySelector('[data-clock-second]').setAttribute('transform',`rotate(${p.second*6} 120 120)`);const text=`${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}:${String(p.second).padStart(2,'0')}`;sign.querySelector('.hanging-digital').innerHTML=[...text].map(c=>c===':'?'<i>:</i>':`<b>${c}</b>`).join('');sign.setAttribute('aria-label',`${cities[city].name} ${text}，可拖曳或用方向鍵調整時鐘位置`);}};
}


